insert into public.questions (category, question, options, correct_answer, verse_reference, verse_text, echo_word, echo_strength, difficulty, translation)
values
  ('Fitness', 'The incline dumbbell curl primarily targets the ______ head of the biceps.', '["Long", "Short"]'::jsonb, 'Long', 'Psalm 91:16', 'With long life I will satisfy him and show him my salvation.', 'long life', 'direct', 'medium', 'NIV'),
  ('Fitness', 'Static stretching means holding a stretch ______, without bouncing.', '["Still", "Moving"]'::jsonb, 'Still', 'Psalm 46:10', 'He says, "Be still, and know that I am God; I will be exalted among the nations, I will be exalted in the earth."', 'still', 'direct', 'easy', 'NIV'),
  ('Fitness', 'The hamstring muscles are located on the ______ of the thigh.', '["Back", "Front"]'::jsonb, 'Back', 'Philippians 3:13', 'Brothers and sisters, I do not consider myself yet to have taken hold of it. But one thing I do: Forgetting what is behind and straining toward what is ahead,', 'behind', 'direct', 'easy', 'NIV'),
  ('Fitness', 'In weightlifting, the point just before a muscle fails and can lift no more is called ______.', '["Failure", "Rest"]'::jsonb, 'Failure', '2 Corinthians 4:8-9', 'We are hard pressed on every side, but not crushed; perplexed, but not in despair; persecuted, but not abandoned; struck down, but not destroyed.', 'struck down, but not destroyed', 'thematic', 'medium', 'NIV'),
  ('Fitness', 'A training program that gradually increases weight or reps over time follows the principle of ______ overload.', '["Progressive", "Passive"]'::jsonb, 'Progressive', 'Philippians 1:6', 'being confident of this, that he who began a good work in you will carry it on to completion until the day of Christ Jesus.', 'began...carry it on to completion (ongoing growth)', 'thematic', 'medium', 'NIV'),
  ('Fitness', 'The recovery period a muscle needs between hard training sessions is called ______.', '["Rest", "Repetition"]'::jsonb, 'Rest', 'Exodus 20:10', 'but the seventh day is a sabbath to the LORD your God. On it you shall not do any work...', 'sabbath / rest', 'direct', 'easy', 'NIV'),
  ('Fitness', 'Exercises that use body weight alone, with no external equipment, are called ______ exercises.', '["Calisthenic", "Isolation"]'::jsonb, 'Calisthenic', '1 Timothy 4:8', 'For physical training is of some value, but godliness has value for all things, holding promise for both the present life and the life to come.', 'physical training', 'thematic', 'hard', 'NIV'),
  ('Fitness', 'Running a marathon relies primarily on which type of endurance?', '["Aerobic", "Anaerobic"]'::jsonb, 'Aerobic', 'Hebrews 12:1', '...let us run with perseverance the race marked out for us,', 'run...race (endurance)', 'thematic', 'medium', 'NIV'),
  ('Nutrition', 'This macronutrient, called "the ______," provides 9 calories per gram — more than double protein or carbs.', '["Fat", "Protein", "Carbohydrate"]'::jsonb, 'Fat', 'Genesis 4:4', 'And Abel also brought an offering—fat portions from some of the firstborn of his flock. The Lord looked with favor on Abel and his offering,', 'fat', 'direct', 'easy', 'NIV'),
  ('Nutrition', 'Calcium gives bones their strength by acting like a natural ______ material in the body.', '["Rock", "Liquid", "Gas"]'::jsonb, 'Rock', 'Psalm 18:2', 'The LORD is my rock, my fortress and my deliverer; my God is my rock, in whom I take refuge, my shield and the horn of my salvation, my stronghold.', 'rock', 'direct', 'easy', 'NIV'),
  ('Nutrition', 'Vitamin D is nicknamed the "______ vitamin" because skin produces it from sunlight exposure.', '["Sun", "Moon", "Star"]'::jsonb, 'Sun', 'Malachi 4:2', 'But for you who revere my name, the sun of righteousness will rise with healing in its rays...', 'sun', 'direct', 'easy', 'NIV'),
  ('Nutrition', 'A diet lacking variety and essential nutrients is often described as ______, meaning empty of what the body needs.', '["Deficient", "Balanced"]'::jsonb, 'Deficient', 'Genesis 1:2', 'Now the earth was formless and empty, darkness was over the surface of the deep, and the Spirit of God was hovering over the waters.', 'empty', 'thematic', 'medium', 'NIV'),
  ('Nutrition', 'Whole grains retain their ______, the nutrient-dense outer layer removed in refined grains.', '["Bran", "Sugar"]'::jsonb, 'Bran', 'Ruth 2:14', 'At mealtime Boaz said to her, "Come over here. Have some bread and dip it in the wine vinegar." When she sat down with the harvesters, he offered her some roasted grain. She ate all she wanted and had some left over.', 'roasted grain', 'thematic', 'hard', 'NIV'),
  ('Nutrition', 'Honey is classified nutritionally as a simple ______.', '["Sugar", "Protein"]'::jsonb, 'Sugar', 'Judges 14:18', '..."What is sweeter than honey? What is stronger than a lion?"...', 'sweeter than honey', 'direct', 'easy', 'NIV'),
  ('Nutrition', 'Fiber''s main role in digestion is to keep things moving ______ through the digestive tract.', '["Regularly", "Slowly"]'::jsonb, 'Regularly', 'Ecclesiastes 3:1', 'There is a time for everything, and a season for every activity under the heavens:', 'time...season (rhythm, regularity)', 'thematic', 'hard', 'NIV'),
  ('Nutrition', 'Bread made without a rising agent is called ______ bread.', '["Unleavened", "Sourdough"]'::jsonb, 'Unleavened', 'Exodus 12:8', 'That same night they are to eat the meat roasted over the fire, along with bitter herbs, and bread made without yeast.', 'bread made without yeast', 'thematic', 'medium', 'NIV'),
  ('Health', 'Leviticus''s instructions for sacrifice describe removing the fat from two ______, the organs that filter waste from the blood.', '["Kidneys", "Liver"]'::jsonb, 'Kidneys', 'Leviticus 3:4', 'both kidneys with the fat on them near the loins, and the long lobe of the liver, which you will remove with the kidneys.', 'kidneys', 'direct', 'medium', 'NIV'),
  ('Health', 'Cardiovascular disease primarily affects which organ?', '["Heart", "Lungs", "Stomach"]'::jsonb, 'Heart', 'Proverbs 4:23', 'Above all else, guard your heart, for everything you do flows from it.', 'heart', 'direct', 'easy', 'NIV'),
  ('Health', 'Which part of a plant, described in Ezekiel as being "for healing," is often the most nutrient-dense part we eat?', '["The leaf", "The root", "The stem"]'::jsonb, 'The leaf', 'Ezekiel 47:12', '...Their fruit will serve for food and their leaves for healing.', 'leaves', 'direct', 'medium', 'NIV'),
  ('Health', 'A wound that will not heal and continues to worsen is described medically as ______.', '["Chronic", "Acute"]'::jsonb, 'Chronic', 'Isaiah 1:6', 'From the sole of your foot to the top of your head there is no soundness—only wounds and welts and open sores, not cleansed or bandaged or soothed with olive oil.', 'not cleansed or bandaged', 'thematic', 'medium', 'NIV'),
  ('Health', 'The skin condition described extensively in Leviticus as requiring priestly examination and quarantine is ______.', '["Leprosy", "Eczema"]'::jsonb, 'Leprosy', 'Leviticus 13:3', 'The priest is to examine the sore on the skin, and if the hair in the sore has turned white and the sore appears to be more than skin deep, it is a defiling skin disease...', 'defiling skin disease', 'thematic', 'medium', 'NIV'),
  ('Health', 'A physician who treats the whole person, not just symptoms, is practicing ______ medicine.', '["Holistic", "Emergency"]'::jsonb, 'Holistic', '3 John 1:2', 'Dear friend, I pray that you may enjoy good health and that all may go well with you, even as your soul is getting along well.', 'good health...soul is getting along well (whole-person)', 'thematic', 'medium', 'NIV'),
  ('Health', 'The medical term for restoring health after illness or injury is ______.', '["Recovery", "Diagnosis"]'::jsonb, 'Recovery', 'Jeremiah 30:17', 'But I will restore you to health and heal your wounds,'' declares the LORD...', 'restore...to health', 'direct', 'easy', 'NIV'),
  ('Health', 'The body''s natural response to injury — redness, heat, and swelling — is called ______.', '["Inflammation", "Infection"]'::jsonb, 'Inflammation', 'Numbers 11:1', '...Then fire from the LORD burned among them and consumed some of the outskirts of the camp.', 'fire...burned', 'thematic', 'hard', 'NIV'),
  ('Science', 'The mitochondria is known as the ______ of the cell.', '["Powerhouse", "Brain", "Outer portion"]'::jsonb, 'Powerhouse', 'Acts 1:8', 'But you will receive power when the Holy Spirit comes on you...', 'power', 'direct', 'medium', 'NIV'),
  ('Science', 'O-negative blood is called the universal type because it can be ______ to patients of any blood type in an emergency.', '["Given", "Received"]'::jsonb, 'Given', 'Acts 20:35', '...''It is more blessed to give than to receive.''', 'give', 'direct', 'easy', 'NIV'),
  ('Science', 'The process by which plants convert sunlight into energy is called ______.', '["Photosynthesis", "Respiration"]'::jsonb, 'Photosynthesis', 'Genesis 1:11', 'Then God said, "Let the land produce vegetation: seed-bearing plants and trees on the land that bear fruit with seed in it, according to their various kinds."', 'produce...bear fruit with seed (growth)', 'thematic', 'medium', 'NIV'),
  ('Science', 'The basic unit of heredity, carrying traits from parent to offspring, is called a ______.', '["Gene", "Cell"]'::jsonb, 'Gene', 'Genesis 5:3', 'When Adam had lived 130 years, he had a son in his own likeness, in his own image; and he named him Seth.', 'likeness...image (inherited traits)', 'thematic', 'hard', 'NIV'),
  ('Science', 'The force that pulls objects toward the earth is called ______.', '["Gravity", "Momentum"]'::jsonb, 'Gravity', 'Job 38:31', 'Can you bind the chains of the Pleiades? Can you loosen Orion''s belt?', 'bind the chains...loosen (cosmic forces)', 'thematic', 'hard', 'NIV'),
  ('Science', 'Water freezes and turns to ______ at 32 degrees Fahrenheit.', '["Ice", "Steam"]'::jsonb, 'Ice', 'Job 38:29', 'From whose womb comes the ice? Who gives birth to the frost from the heavens', 'ice', 'direct', 'easy', 'NIV'),
  ('Science', 'The layer of gases surrounding the Earth is called the ______.', '["Atmosphere", "Crust"]'::jsonb, 'Atmosphere', 'Genesis 1:6', 'And God said, "Let there be a vault between the waters to separate water from water."', 'vault between the waters (the sky)', 'thematic', 'medium', 'NIV'),
  ('Science', 'The human body''s largest organ, covering and protecting everything inside it, is the ______.', '["Skin", "Liver"]'::jsonb, 'Skin', 'Job 2:4', '"Skin for skin!" Satan replied. "A man will give all he has for his own life."', 'skin', 'direct', 'easy', 'NIV'),
  ('Food', 'Which food is one of the best natural sources of omega-3 fatty acids?', '["Fish", "Chicken"]'::jsonb, 'Fish', 'Luke 5:6', 'When they had done so, they caught such a large number of fish that their nets began to break.', 'fish', 'direct', 'easy', 'NIV'),
  ('Food', 'The anti-inflammatory spice turmeric comes from which part of a plant?', '["The root", "The leaf", "The stem"]'::jsonb, 'The root', 'Isaiah 53:2', 'He grew up before him like a tender shoot, and like a root out of dry ground...', 'root', 'direct', 'easy', 'NIV'),
  ('Food', 'Walnuts are nicknamed "______ food" for their omega-3 content, believed to support memory and focus.', '["Brain", "Muscle"]'::jsonb, 'Brain', 'Romans 12:2', '...be transformed by the renewing of your mind...', 'mind (brain function)', 'thematic', 'medium', 'NIV'),
  ('Food', 'Iron is essential for making hemoglobin, the protein that makes blood appear ______.', '["Red", "Blue", "Clear"]'::jsonb, 'Red', '2 Kings 3:22', '...the sun was shining on the water. To the Moabites across the way, the water looked red—like blood.', 'red...like blood', 'direct', 'easy', 'NIV'),
  ('Food', 'Olive oil is prized nutritionally as a source of ______ fat, the heart-healthy kind.', '["Monounsaturated", "Trans"]'::jsonb, 'Monounsaturated', 'Deuteronomy 8:8', 'a land with wheat and barley, vines and fig trees, pomegranates, olive oil and honey,', 'olive oil', 'direct', 'medium', 'NIV'),
  ('Food', 'Grapes, when dried, become the snack known as ______.', '["Raisins", "Prunes"]'::jsonb, 'Raisins', '1 Samuel 25:18', '...a hundred cakes of raisins and two hundred cakes of pressed figs, and loaded them on donkeys.', 'raisins', 'direct', 'easy', 'NIV'),
  ('Food', 'Locusts, mentioned in scripture as a food source, are actually a type of ______ — a high-protein food many cultures still eat.', '["Insect", "Grain"]'::jsonb, 'Insect', 'Matthew 3:4', 'John''s clothes were made of camel''s hair, and he had a leather belt around his waist. His food was locusts and wild honey.', 'locusts', 'direct', 'medium', 'NIV'),
  ('Food', 'Milk is one of the best natural sources of ______, essential for strong bones and teeth.', '["Calcium", "Iron"]'::jsonb, 'Calcium', 'Exodus 3:8', '...a land flowing with milk and honey...', 'milk', 'thematic', 'medium', 'NIV');
